function init() {
scene = new THREE.Scene();
camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
camera.position.z = 5;

renderer = new THREE.WebGLRenderer();
renderer.setSize(window.innerWidth, window.innerHeight);
document.body.appendChild(renderer.domElement);

const loader = new GLTFLoader ();
loader.load(‘particles three js1.glb’, function (gltf) {
model = gltf.scene;
scene.add(model);

// Удаляем все материалы
model.traverse(function (child) {
if (child.isMesh) child.material.dispose();
});

const particleMaterial = new THREE.PointsMaterial({ color: 0xffffff, size: 0.1 });
particles = new THREE.BufferGeometry().setFromPoints([]);

// Добавляем частицы в вершины
model.traverse(function (child) {
if (child.isMesh) {
particles.merge(child.geometry, child.matrixWorld);
}
});

const particlesSystem = new THREE.Points(particles, particleMaterial);
scene.add(particlesSystem);
});
}

