public class UIArchiveScreen : BaseUIScreen
    {
        [SerializeField]
        private ArchiveContent _archiveContent;
        [SerializeField]
        private PanelSearch _panelSearch;

        [Inject]
        private StatisticsProvider _statisticsProvider;

        private List<ArchivePanel> _currentArchivePanels;
        private List<ArchivePanel> _currentArchivePanelsDate;
        private List<ArchivePanel> _currentArchivePanelsName;

        public override void Initialized()
        {
            base.Initialized();

            _statisticsProvider.Connecting();
            var users = _statisticsProvider.GetUsers();
            _statisticsProvider.Disconnect();

            _archiveContent.Initialize(users);
            _panelSearch.Initialize(users);

            _panelSearch.OnChangeDate += DropdownChangedDate;
            _panelSearch.OnChangeName += DropdownChangedName;

            _currentArchivePanels = _archiveContent.ArchivePanels;
            _currentArchivePanelsName = _archiveContent.ArchivePanels;
            _currentArchivePanelsDate = _archiveContent.ArchivePanels;
        }

        private void DropdownChangedDate(string text)
        {
            List<ArchivePanel> foundDate = _archiveContent.ArchivePanels;

            if (text != "Все")
            {
                DateTime stringDate = DateTime.ParseExact(text, "yyyy - MM - dd", CultureInfo.InvariantCulture);

                foundDate = _archiveContent.ArchivePanels.FindAll(date => date._BaseUser.Date.Date == stringDate.Date);
            }
            _currentArchivePanelsDate = foundDate;
            UpdateContent(foundDate, _currentArchivePanelsName);
        }
        private void DropdownChangedName(string text)
        {
            List<ArchivePanel> foundName = _archiveContent.ArchivePanels;

            if (text != "Все")
            {
                foundName = _archiveContent.ArchivePanels.FindAll(date => date._BaseUser.Name == text);
            }
            _currentArchivePanelsName = foundName;
            UpdateContent(foundName, _currentArchivePanelsDate);

        }

        private void UpdateContent(IEnumerable<ArchivePanel> panelsName, IEnumerable<ArchivePanel> panelsDate)
        {
            foreach (var panel in _currentArchivePanels)
            {
                panel.Deactive();
            }

            var panels = panelsName.Intersect(panelsDate).ToList();

            foreach (var panel in panels)
            {
                panel.Active();
            }
        }
    }
}

